import json
from pathlib import Path
base=Path(__file__).resolve().parent.parent
raw={k:json.loads((base/'research'/f'{k}.json').read_text()) for k in ['google','slack','notion','github']}
guides=[]
g=raw['google']
guides.append(dict(id='gmail',name='Gmail',website='https://developers.google.com/workspace/gmail',category='Email',color='#c45444',initials='M',difficulty='high',difficultyLabel='Security assessment',headline=g['verdict']['headline'],summary=g['verdict']['reason'],scenario=g['scenario'],nextAction=g['verdict']['nextAction'],checkedAt=g['investigatedAt'],status='reviewed',evidenceLabel='Console form inspected',effort='45–90 min',effortBasis=g['time']['testSetup'],wait='~6 weeks review; assessment varies',waitBasis=g['time']['reviewWait']+' '+g['time']['timingNuance'],preparation=g['time']['productionPrep'],test=g['testVsProduction']['testing'],production=g['testVsProduction']['production'],caveat=g['testVsProduction']['internalAlternative']+' '+g['testVsProduction']['adminNuance'],steps=[dict(title=s['title'],detail=s['action'],owner=s['owner'],doneWhen=s['doneWhen'],sourceIds=s['sourceIds']) for s in g['steps']],blockers=[dict(trigger=b['symptom'],action=b['remedy'],sourceIds=b['sourceIds']) for b in g['blockers']],agentCan=g['agentBoundary']['canDo'],humanMust=g['agentBoundary']['humanMustDo'],attempts=[dict(action='Inspected Google Auth platform → Clients → Create client → Web application',observation='; '.join(g['setupAttempt']['observed']),result=g['setupAttempt']['handoff'],notTested='; '.join(g['setupAttempt']['notTested']))],corrections=g['learnedAndCorrected'],uncertainties=g['uncertainties'],sources=g['sources'],scopes=g['scopeChoices']))
s=raw['slack']
guides.append(dict(id='slack',name='Slack',website='https://api.slack.com/apps',category='Communication',color='#694068',initials='#',difficulty='high',difficultyLabel='Marketplace review',headline=s['verdict'],summary='A pilot install and a commercial launch are different milestones. Check product eligibility before investing in review.',scenario=s['scenario'],nextAction=s['firstDecision'],checkedAt=s['researchedAt'],status='reviewed',evidenceLabel='Setup entry point tested',effort='1–3 hours',effortBasis=s['timing']['activeSetup']['basis'],wait='Up to 10 business days + 10 weeks',waitBasis=s['timing']['providerWait']['value']+'. '+s['timing']['providerWait']['basis']+' '+s['timing']['unboundedDependency'],preparation=s['timing']['productionPreparation']['value']+' — '+s['timing']['productionPreparation']['basis'],test=s['testVsProduction']['test'],production=s['testVsProduction']['production'],caveat=s['testVsProduction']['caveat'],steps=s['steps'],blockers=[dict(trigger=b['trigger'],action=b['nextAction'],sourceIds=b['sourceIds']) for b in s['blockers']],agentCan=s['agentCanDo'],humanMust=s['humanMustDo'],attempts=[dict(action=a['action'],observation=a['observation'],result=a['result'],notTested=a['notTested']) for a in s['attempts']],corrections=s['corrections'],uncertainties=s['uncertainties'],sources=s['sources']))
for key in ['notion','github']:
 d=raw[key]
 guides.append(dict(id=key,name=d['name'],website=d['website'],category='Knowledge' if key=='notion' else 'Developer tools',color='#222625',initials='N' if key=='notion' else 'GH',difficulty='low' if key=='notion' else 'moderate',difficultyLabel='Direct distribution' if key=='notion' else 'Customer admin gates',headline=d['verdict'],summary='OAuth distribution and optional Marketplace discovery are separate paths.' if key=='notion' else 'Fast registration; organization permissions can remain a customer-side dependency.',scenario=d['scope'],nextAction=d['steps'][0]['detail'],checkedAt=d['checkedAt'],status='reviewed',evidenceLabel='Setup entry point tested',effort=d['effort']['value'],effortBasis=d['effort']['kind']+'. '+d['effort']['assumptions'],wait='No mandatory listing wait' if key=='notion' else 'No standard provider review',waitBasis=d['wait']['value']+'. '+d['wait'].get('optional',d['wait'].get('conditional',''))+' Basis: '+d['wait']['kind'],test='Register the app and authorize a test account. A successful connection still needs an actual API call and refresh test.',production='Direct OAuth distribution is documented without a Marketplace listing. Choose Any workspace at creation for broad distribution.' if key=='notion' else 'Follow the registration and authorization path, then validate access in the customer’s actual organization. No general review stage is described in that path; this is not a guarantee against account-specific enforcement.',steps=[dict(title=x['title'],detail=x['detail'],owner=x['owner'],sourceIds=x['sources']) for x in d['steps']],blockers=[dict(trigger=x['problem'],action=x['next'],owner=x['owner'],sourceIds=x['sources']) for x in d['blockers']],agentCan=d['agentCan'],humanMust=d['humanMust'],attempts=[dict(action=x['action'],observation=x['observed'],result=x['result']) for x in d['attempts']],corrections=[dict(after=x) for x in d['corrections']],uncertainties=d['uncertainties'],sources=d['sources']))
# Reading order emphasizes the range of launch paths.
guides.sort(key=lambda x:['github','notion','slack','gmail'].index(x['id']))
(base/'data'/'guides.json').write_text(json.dumps(guides,indent=2,ensure_ascii=False)+'\n')
